sys_variable_value.value:
(function(outputs, inputs) {
    var response = inputs.ai_response;
    if (!response) return;

    // Use a more robust split: comma followed by a space, 
    // to avoid breaking descriptions that contain internal commas.
    var pairs = response.split(', ');

    pairs.forEach(function(pair) {
        var parts = pair.split(':');
        if (parts.length >= 2) {
            var key = parts[0].trim().toLowerCase();
            // Join the rest back in case the value itself contained a colon
            var value = parts.slice(1).join(':').trim(); 

            // Existing Mappings
            if (key.indexOf('number') > -1) outputs.invoice_number = value;
            if (key.indexOf('date') > -1 && key.indexOf('invoice') > -1) outputs.invoice_date = value;
            if (key.indexOf('tax') > -1) outputs.tax_amount = value;
            if (key.indexOf('amount') > -1 && key.indexOf('tax') == -1) outputs.total_amount = value;
            if (key.indexOf('company') > -1) outputs.company_name = value;

            // --- NEW MAPPINGS ---
            
            // Description (grabs the long text block)
            if (key.indexOf('description') > -1) {
                outputs.description = value;
            }

            // Quantity (Anzahl)
            if (key.indexOf('quantity') > -1) {
                outputs.quantity = value;
            }

            // Price per Unit (Preis pro Einheit)
            if (key.indexOf('price per unit') > -1 || key.indexOf('einheit') > -1) {
                outputs.price_per_unit = value;
            }
        }
    });


})(outputs, inputs);

